      if (typeof parsed.currentTierIndex !== 'number' || isNaN(parsed.currentTierIndex)) {
        parsed.currentTierIndex = 0;
      }
      return accrueEarnings(parsed);
    }
  } catch (error) {
    console.log('[Earn] Error loading local data:', error);
  }

